    "note_id": "6a812a31000000003301953a",
    "title": "某伊奶酪脆新版配料表更改，新版干酪少",
    "author": "七七出出",
    "publish_time": "08-16",
    "body": "很爱吃奶酪脆，今天又买了新的，闲着无聊看配料表发觉不对劲，找出还没吃完的旧版一对比，真是偷工减料。自存一下避雷用。\n配料核心区别:\n1. 干酪含量：旧版干酪添加量≥76%，比新版的≥63%高出13个百分点，奶酪占比更高。\n2. 糖类添加：新版同时使用海藻糖+白砂糖；旧版仅用白砂糖，没有添加海藻糖。\n#食品质量安全 #超干净的配料表 #奶酪脆",
    "likes": "13",
    "collects": "0",
    "comments_count": "3",
    "sentiment_guess": "中性/其他",
