    "body": "好物分享来啦～\n1 伊利新品脆奶酪 很好、奶味浓郁奶味足 微咸口、非油炸，很脆 这个我一天一包\n2 芥末牛脆脆、很多牛脆脆我都吃过了、这个最过过瘾，喜欢芥末的姐妹一定要试试\n3 参山见 红参饮 ，说是去湿气、看不出来、我睡觉前喝、嗯、似乎对睡眠一点帮助\n4 韩国🇰🇷胶原蛋白饮、好喝、很好喝，小甜水、就是饮料\n5 楼上的芥末鱼条，芥末味不重、嚼着玩的小零食\n6 山姆牛肉酱、糊气烧椒味重、这个见仁见智、我觉得好吃\n7 江中的山楂鸡内金、我宝宝吃了之后、我觉得有好好吃饭、比钙铁锌口服液管用、我也吃了、吃了之后更饿了…口感就是酸酸的软糖、这个baby不好好吃饭的可以试试\n8 胖东来鲜牛奶、比山姆浓郁、比山姆好喝\n9 乌江榨菜、这个都知道、我觉得菜心最好吃#伊利#杨生记 #东阿阿胶 #楼上 #胶原蛋白 #山姆 #江中 #胖东来 #乌江榨菜",
    "likes": "1",
    "collects": "2",
    "comments_count": "0",
    "sentiment_guess": "正面",
