    "note_id": "6ad646e9000000000c00c934",
    "title": "分享一款难吃零食",
    "author": "lalarunrun",
    "publish_time": "编辑于 10-20 浙江",
    "body": "伊利脆奶酪\n可以尝试一下\n十分歹毒\n我说怎么样子和沃尔玛的那款一样\n还是一个代工厂\n这款性价比怎么这么高\n沃尔玛一包4颗\n这个一包n颗\n没想到啊没想到\n伊利做坏事的时候就是便宜量大\n已经不能用不好吃形容了\n我也很少会为难吃的零食这么长篇大论\n苦难是滋生文学的土壤\n真的太难吃了\n我还不爱浪费粮食，但是每吃一颗都感觉在被击打\n放弃了\n就这样吧\n如果这件事上必须要有个罪人，那只能是伊利\n怎么能这么难吃\n宗教说人浪费的粮食到了地下还要继续吃完\n要不我寄给你吧\n免得我去了地下还要吃\n昨天还给了一包给小朋友，她甜甜地说了谢谢\n不知道她回去打开吃的时候，会不会恨我\n给同事了一包\n她吃了一颗\n被仅退货了\n吃完还在那漱口",
    "likes": "1",
    "collects": "0",
    "comments_count": "3",
    "sentiment_guess": "负面",
