    "note_id": "6adef1bd000000001503a283",
    "title": "这波贪了，不该为了“南宫碗”买联名脆奶酪",
    "author": "Salad",
    "publish_time": "3天前 浙江",
    "body": "主要是想要那个“南宫碗”，于是顺手买了联名的妙芝脆奶酪\n\n原本以为口感会和浪味仙差不多，实际吃起来很甜，偏齁；其次奶味和常见的奶酪奶味不太一样；另外“脆奶酪”的脆感也有些奇怪，如果是软质奶酪，我可能更容易接受\n\n原本觉得，买两包零食送个碗挺值的；现在完全成了买椟还珠，花大几十主要买了个碗，还附带两包我吃完一包就不会再碰的零食。这个价格，拿去买深泽直人设计的MUJI青白瓷，不是更香吗？\n\n#凡人修仙传 #妙芝脆奶酪 #南宫婉 #联名周边 #零食记录 #伊利 #妙芝 #韩立",
